# GPT2 B5 model-dispatch development probe. Paste the whole file into Colab.
USE_GOOGLE_DRIVE = True
INPUT_ZIP = ""  # Passed minimal B4 ZIP or a matching B5 result ZIP. No weights reconstructed.
import base64,io,zipfile,tempfile,hashlib,json,sys
from pathlib import Path
PAYLOAD = ''
def start():
 root=Path(tempfile.mkdtemp(prefix="gpt2_b5_dispatch_source_"))
 with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as z:
  manifest=json.loads(z.read("SOURCE_MANIFEST.json"))
  for n,h in manifest.items():
   data=z.read(n)
   if hashlib.sha256(data).hexdigest()!=h:raise RuntimeError("Source digest mismatch: "+n)
   if Path(n).name!=n:raise RuntimeError("Unsafe source path")
   (root/n).write_bytes(data)
  (root/"SOURCE_MANIFEST.json").write_bytes(z.read("SOURCE_MANIFEST.json"))
 paths=sys.path[:];names=["b5_protocol","launch_b5","process_io"]
 old={n:sys.modules[n] for n in names if n in sys.modules}
 for n in names:sys.modules.pop(n,None)
 sys.path.insert(0,str(root))
 try:
  from launch_b5 import start as launch
  launch(USE_GOOGLE_DRIVE,INPUT_ZIP)
 finally:
  for n in names:sys.modules.pop(n,None)
  sys.modules.update(old);sys.path[:]=paths
if __name__=="__main__":start()
